#!/bin/bash\n# Setup script for VideoPlayerApp\n\necho \"🎬 VideoPlayerApp Setup Script\"\necho \"=============================\"\necho \"\"\n\n# Check Node.js\necho \"✓ Checking Node.js...\"\nif ! command -v node &> /dev/null; then\n    echo \"✗ Node.js not found. Please install Node.js 16+\"\n    exit 1\nfi\necho \"  Node.js version: $(node --version)\"\n\n# Check npm\necho \"✓ Checking npm...\"\nif ! command -v npm &> /dev/null; then\n    echo \"✗ npm not found. Please install npm\"\n    exit 1\nfi\necho \"  npm version: $(npm --version)\"\n\n# Check Java\necho \"✓ Checking Java...\"\nif ! command -v java &> /dev/null; then\n    echo \"✗ Java not found. Please install JDK 11+\"\n    exit 1\nfi\necho \"  Java version: $(java -version 2>&1 | head -1)\"\n\n# Check Android SDK\necho \"✓ Checking Android SDK...\"\nif [ -z \"$ANDROID_HOME\" ]; then\n    echo \"⚠ ANDROID_HOME not set. Skipping Android SDK check.\"\n    echo \"  To set it: export ANDROID_HOME=/path/to/android-sdk\"\nelse\n    echo \"  Android SDK: $ANDROID_HOME\"\nfi\n\necho \"\"\necho \"✓ Installing npm dependencies...\"\nnpm install\n\necho \"\"\necho \"✅ Setup complete!\"\necho \"\"\necho \"Next steps:\"\necho \"1. Connect an Android device or start an emulator\"\necho \"2. Run: npm start\"\necho \"3. In another terminal: npm run android\"\necho \"\"\necho \"For more information, see QUICKSTART.md\"\n